async function main() {
    console.log("🚀 Starting Fresh Seeding (EXTENDED 10-PAGE EDITION)...");

    // 1. Clear ALL existing data (Order matters for Foreign Keys)
    console.log("🧹 Clearing existing data...");
    await db.delete(userQuests);
    await db.delete(quests);
    await db.delete(readingProgress);
    await db.delete(storyPins);
    await db.delete(storyPageFavorites);
    await db.delete(storyPages);
    await db.delete(stories);
    await db.delete(categories);
    await db.delete(heroes);
    await db.delete(session);
    await db.delete(account);
    await db.delete(verification);
    await db.delete(user);

    // 2. Insert categories
    const [fabelCat, legendaCat, dongengCat] = await db.insert(categories).values([
        { name: "Fabel", description: "Cerita tentang hewan yang berperilaku seperti manusia." },
        { name: "Legenda", description: "Cerita rakyat yang dianggap benar-benar terjadi." },
        { name: "Dongeng", description: "Cerita khayalan atau fantasi yang penuh keajaiban." },
    ]).returning();

    // 3. Insert Quests
    await db.insert(quests).values([
        { 
            title: "Pembaca Pemula", 
            description: "Selesaikan membaca 1 cerita", 
            xpReward: 50, 
            pointsReward: 1, 
            type: "READING", 
            targetValue: 1, 
            isDaily: true 
        },
        { 
            title: "Pecinta Cerita", 
            description: "Berikan 2 hati pada halaman cerita", 
            xpReward: 30, 
            pointsReward: 1, 
            type: "FAVORITE", 
            targetValue: 2, 
            isDaily: true 
        },
        { 
            title: "Penjelajah Ulung", 
            description: "Selesaikan membaca 2 cerita hari ini", 
            xpReward: 100, 
            pointsReward: 2, 
            type: "READING", 
            targetValue: 2, 
            isDaily: true 
        },
        { 
            title: "Kolektor Momen", 
            description: "Berikan 5 hati pada halaman favoritmu", 
            xpReward: 60, 
            pointsReward: 2, 
            type: "FAVORITE", 
            targetValue: 5, 
            isDaily: true 
        },
        { 
            title: "Penanda Jejak", 
            description: "Simpan posisi membaca di 1 cerita", 
            xpReward: 40, 
            pointsReward: 1, 
            type: "PIN", 
            targetValue: 1, 
            isDaily: true 
        },
        { 
            title: "Pustakawan Cilik", 
            description: "Berikan 3 hati pada cerita yang berbeda", 
            xpReward: 45, 
            pointsReward: 1, 
            type: "FAVORITE", 
            targetValue: 3, 
            isDaily: true 
        }
    ]);

    const categoryMap: Record<string, number> = {
        "Fabel": fabelCat.id,
        "Legenda": legendaCat.id,
        "Dongeng": dongengCat.id
    };

    // 4. Seeding Logic with 10-page enforcement
    for (const story of STORIES_DATA) {
        const [insertedStory] = await db.insert(stories).values({
            title: story.title,
            slug: story.slug,
            preview: story.preview,
            content: story.content, 
            categoryId: categoryMap[story.category],
            status: "published",
            thumbnailUrl: `/images/covers/${story.slug}.png`
        }).returning();

        const paragraphs = story.content.split("\n\n");
        
        // Loop to create exactly 10 pages
        for (let p = 0; p < 10; p++) {
            // Take 2 paragraphs per page
            const startIndex = p * 2;
            const pageContent = paragraphs.slice(startIndex, startIndex + 2).join("\n\n") 
                || `Terima kasih telah membaca ${story.title}. Semoga pelajaran berharga ini bisa menjadi inspirasi dalam kehidupan kita sehari-hari agar selalu berbuat baik dan penuh kasih sayang terhadap sesama makhluk ciptaan Tuhan yang sangat indah ini.`;

            await db.insert(storyPages).values({
                storyId: insertedStory.id,
                pageNumber: p + 1,
                content: pageContent
            });
        }
        console.log(`✅ Fully Seeded (GHOST-IMAGE EDITION - 10 Pages): ${story.title}`);
    }

    console.log("✨ Seeding completed successfully!");
    process.exit(0);
}

main().catch((err) => {
    console.error("❌ Seeding failed:", err);
    process.exit(1);
});
